S = "Hakeem Force Academy"
QS = [
(S, "How many idols were placed in and around the Kaaba before the conquest of Makkah?", ["300", "360", "313", "400"], 1,
 "Traditional sources say 360 idols stood around the Kaaba when the Holy Prophet (PBUH) entered Makkah in 8 AH. He had them removed and the Kaaba cleansed.", "The idol Hubal was the chief idol of the Quraysh inside the Kaaba.", 1),
(S, "How many books make up the Kutub-e-Sittah (the six authentic collections of Hadith)?", ["4", "5", "6", "7"], 2,
 "Kutub-e-Sittah literally means the six books: Sahih Bukhari, Sahih Muslim, Sunan Abu Dawud, Jami Tirmidhi, Sunan Nasai and Sunan Ibn Majah.", "Sahih Bukhari, compiled by Imam Bukhari, is generally regarded as the most authentic of them.", 1),
(S, "How many Madani surahs does the Holy Quran contain, according to the common Pakistani textbook count?", ["86", "28", "30", "114"], 1,
 "Of the 114 surahs, 86 are Makki and 28 are Madani. Madani surahs were revealed after the Hijrat.", "Scholars differ slightly on a few surahs, so some books give slightly different counts.", 3),
(S, "How many manzils (stages) is the Holy Quran divided into?", ["30", "7", "4", "10"], 1,
 "The Quran is divided into seven manzils so that it can be recited in one week. Each manzil is read on one day of the week.", "The Quran is also divided into 30 paras (juz).", 2),
(S, "How many masarif (heads of expenditure) of zakat are mentioned in Surah At-Tawbah?", ["5", "7", "8", "10"], 2,
 "Surah At-Tawbah (9:60) names eight categories of zakat recipients: the poor, the needy, zakat collectors, those whose hearts are to be reconciled, slaves, debtors, the cause of Allah and the wayfarer.", "Zakat is one of the five pillars of Islam.", 2),
(S, "What is the total number of members of the Senate of Pakistan?", ["100", "104", "96", "87"], 2,
 "The Senate has 96 members: 23 from each of the four provinces (92) plus 4 from the Islamabad Capital Territory. A November 2025 report still describes a 96-member Senate", "The Senate had 104 members until the FATA seats were phased out after FATA merged into Khyber Pakhtunkhwa in 2018.", 1),
(S, "How many Senate seats are allocated to each province of Pakistan?", ["14", "22", "23", "25"], 2,
 "Each province has 23 Senate seats: 14 general, 4 for women, 4 for technocrats and 1 for non-Muslims.", "The Senate is a permanent house; half of its members retire every three years.", 1),
(S, "How many general (directly elected) seats does Punjab have in the National Assembly of Pakistan?", ["141", "148", "173", "371"], 0,
 "Under the 2024 delimitation Punjab has 141 general seats in the 336-seat National Assembly. With its 32 reserved seats for women, Punjab's share rises to 173.", "The National Assembly has 266 general seats, 60 for women and 10 for non-Muslims.", 1),
(S, "How many Nishan-e-Haider awards have been given so far, according to the commonly cited count?", ["8", "10", "11", "12"], 2,
 "The commonly cited current count is 11 recipients, all awarded posthumously. Older sources say 10, and the status of the eleventh name is sometimes disputed.", "Nishan-e-Haider is the highest military gallantry award of Pakistan.", 2),
(S, "How many nuclear-weapon states are recognised under the Nuclear Non-Proliferation Treaty (NPT)?", ["3", "5", "7", "9"], 1,
 "The NPT recognises five nuclear-weapon states, those that tested before 1 January 1967: the USA, Russia, the UK, France and China. Pakistan, India, Israel and North Korea are outside this list.", "The NPT came into force in 1970.", 1),
(S, "Into how many paras (juz) is the Holy Quran divided?", ["28", "30", "40", "114"], 1,
 "The Quran is divided into 30 paras of roughly equal length so it can be read in a month. This is separate from its 114 surahs.", "The first para is Alif Lam Meem.", 1),
(S, "How many players are on the court for one team in a volleyball match?", ["5", "6", "7", "11"], 1,
 "A volleyball team has six players on the court at a time, three at the net and three at the back.", "A basketball team has five players on court.", 1),
(S, "How many players of one team are on the court at a time in basketball?", ["5", "6", "7", "11"], 0,
 "Each basketball team plays with five players on the court at a time.", "A team may have up to 12 players in total on its roster in international games.", 1),
(S, "Which rivers were allotted to Pakistan under the Indus Waters Treaty of 1960, and how many are they?", ["Three western rivers: Indus, Jhelum and Chenab", "Three eastern rivers: Ravi, Beas and Sutlej", "Two rivers: Indus and Sutlej", "Five rivers: all Punjab rivers"], 0,
 "The treaty gave Pakistan the three western rivers (Indus, Jhelum, Chenab). India received the three eastern rivers (Ravi, Beas, Sutlej).", "The treaty was brokered by the World Bank.", 1),
(S, "How many sides does a quadrilateral (such as a square) have?", ["3", "4", "5", "6"], 1,
 "A quadrilateral is a closed figure with four straight sides, and a square is a special case with four equal sides and four right angles.", "The angles of any quadrilateral add up to 360 degrees.", 1),
(S, "How many consecutive matches did squash legend Jahangir Khan win in his unbeaten run between 1981 and 1986?", ["355", "455", "555", "655"], 2,
 "Jahangir Khan won 555 consecutive matches over about five and a half years, a record recognised in the Guinness Book of Records as the longest winning streak in a professional sport.", "He won the British Open ten times in a row.", 1),
(S, "How many states are there in the United States of America?", ["48", "50", "51", "52"], 1,
 "The USA has 50 states. Alaska and Hawaii were the last to join in 1959.", "Washington, D.C. is a federal district, not a state.", 1),
(S, "How many surahs (chapters) are there in the Holy Quran?", ["110", "112", "114", "116"], 2,
 "The Holy Quran has 114 surahs, beginning with Al-Fatiha and ending with An-Nas.", "86 surahs are Makki and 28 are Madani by the common count.", 1),
(S, "Which is the longest surah of the Holy Quran?", ["Al-Imran", "Al-Baqarah", "An-Nisa", "Al-Maidah"], 1,
 "Surah Al-Baqarah has 286 verses and is the longest surah of the Quran.", "It is the second surah of the Quran.", 1),
(S, "Which is the shortest surah of the Holy Quran?", ["Al-Ikhlas", "Al-Asr", "Al-Kawthar", "An-Nasr"], 2,
 "Surah Al-Kawthar has only three verses and the fewest words, so it is the shortest surah.", "It is surah number 108.", 1),
(S, "In which surah is the longest verse of the Holy Quran?", ["Al-Baqarah", "Al-Imran", "An-Nisa", "Al-Anam"], 0,
 "The longest verse is Ayat ad-Dayn (verse 282) about written contracts of debt, in Surah Al-Baqarah.", "Ayat al-Kursi is verse 255 of the same surah.", 1),
]
